std::vector<Kernel::Point_3> pts(points.begin(), points.end());
if (pts.empty()) return Kernel::Plane_3(0, 0, 0, 0);
if (pts.size() == 1) return Kernel::Plane_3(pts[0], Kernel::Vector_3(0, 0, 1));
if (pts.size() == 2) return Kernel::Plane_3(pts[0], pts[1], pts[0] + Kernel::Vector_3(0, 0, 1));

Kernel::Point_3 centroid(0, 0, 0);
for (const auto& p : pts) {
    centroid = centroid + Kernel::Vector_3(p.x(), p.y(), p.z());
}
centroid = Kernel::Point_3(centroid.x() / pts.size(), centroid.y() / pts.size(), centroid.z() / pts.size());

double xx = 0, xy = 0, xz = 0, yy = 0, yz = 0, zz = 0;
for (const auto& p : pts) {
    double dx = p.x() - centroid.x();
    double dy = p.y() - centroid.y();
    double dz = p.z() - centroid.z();
    xx += dx * dx; xy += dx * dy; xz += dx * dz;
    yy += dy * dy; yz += dy * dz;
    zz += dz * dz;
}

CGAL::Matrix_3x3 M(xx, xy, xz, xy, yy, yz, xz, yz, zz);
CGAL::Vector_3 e;
CGAL::eigen_decomposition(M, e);

double nx = e[0], ny = e[1], nz = e[2];
if (nx * nx + ny * ny + nz * nz < 1e-12) {
    nx = 0; ny = 0; nz = 1;
}

return Kernel::Plane_3(centroid, Kernel::Vector_3(nx, ny, nz));

